package com.bank.portal.repository; import com.bank.portal.domain.*; import java.time.LocalDateTime; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface TransactionRepository extends JpaRepository<CardTransaction,Long>{ List<CardTransaction> findTop8ByCardCustomerIdOrderByTransactionDateDesc(Long customerId); List<CardTransaction> findTop10ByCardCustomerIdOrderByTransactionDateDesc(Long customerId); List<CardTransaction> findTop8ByOrderByTransactionDateDesc(); List<CardTransaction> findByCardCustomerIdOrderByTransactionDateDesc(Long customerId); @Query("select t from CardTransaction t where (:cardId is null or t.card.id=:cardId) and (:customerId is null or t.card.customer.id=:customerId) and (:merchantId is null or t.merchant.id=:merchantId) and (:type is null or t.transactionType=:type) and (:status is null or t.status=:status) and (:from is null or t.transactionDate>=:from) and (:to is null or t.transactionDate<=:to) order by t.transactionDate desc") List<CardTransaction> search(@Param("cardId") Long cardId,@Param("customerId") Long customerId,@Param("merchantId") Long merchantId,@Param("type") TransactionType type,@Param("status") TransactionStatus status,@Param("from") LocalDateTime from,@Param("to") LocalDateTime to); @Query("select coalesce(sum(t.amount),0) from CardTransaction t where t.transactionType=:type and t.status='SUCCESS' and t.card.id=:cardId and t.transactionDate between :from and :to") java.math.BigDecimal sumForCard(@Param("cardId")Long cardId,@Param("type")TransactionType type,@Param("from")LocalDateTime from,@Param("to")LocalDateTime to);}
